window.RP_SESSION={"id":"S-ed35a68b77cb","messages":[{"id":"RP-II-0122414","time":"2026-07-23T01:15:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122415","time":"2026-07-23T01:16:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122416","time":"2026-07-23T01:16:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122417","time":"2026-07-23T01:16:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"탐정은 길을 보았다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122418","time":"2026-07-23T01:19:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"무척이나 낯선 길. 탐정의 지식으로도 이 길이 어디로 이어지는 지는 아무 것도 알아내지 못 했다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122419","time":"2026-07-23T01:19:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그는 무작정 걸었다. 평소의 그라면 하지 않았을 경솔한 행동이었다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122420","time":"2026-07-23T01:19:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"하지만 한 편으로는 이 길이 어디로 이어지는 지, 알아내고 싶은 호기심 때문일지도 몰랐다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122421","time":"2026-07-23T01:20:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122422","time":"2026-07-23T01:21:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122423","time":"2026-07-23T01:21:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'도리안 H 바이덴스'의 지능 판정 :\n[1] + [3] = [4]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0122424","time":"2026-07-23T01:22:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"기이한 일이었다. 아무리 걸어도 이 장소에 대한 단서를 얻을 수가 없었다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122425","time":"2026-07-23T01:23:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"하지만 그것은 더욱 탐정의 호기심을 자극 하는 일이었다. 마치 그를 유혹하려는 듯. 미지가 그에게 손짓하고 있었다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122426","time":"2026-07-23T01:24:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122427","time":"2026-07-23T01:24:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'도리안 H 바이덴스'의 의지 판정 :\n[1] + [2] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0122428","time":"2026-07-23T01:24:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그는 도저히 그 유혹을 뿌리칠 수가 없었다. 기이한 일이다. 하지만 상관없다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122429","time":"2026-07-23T01:25:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"이젠 아무래도 좋았다. 그저 그는 답을 보기위해 계속해서 발걸음을 옮길 뿐이었다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122430","time":"2026-07-23T01:26:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"점점 무너져가는 아슬아슬한 길목을 따라 걸으며...","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122431","time":"2026-07-23T01:27:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"어느덧 그가 도달한 곳에는 낯선 존재가 탐정을 내려다보고 있었다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122432","time":"2026-07-23T01:28:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"탐정은 고개를 들어, 그 존재를 올려다봤다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122433","time":"2026-07-23T01:28:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122434","time":"2026-07-23T01:29:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"낮설지만 낮설지가 않았다. 그의 오랜 무의식은 그 이름을 알고 있었을 터였다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122435","time":"2026-07-23T01:29:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그 존재는 탐정을 내려다 보기만 할 뿐 아무 말도 하지 않았다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122436","time":"2026-07-23T01:30:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그럼에도 탐정은 그 존재가 말하고자 하는 바를 유추 할 수 있었다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122437","time":"2026-07-23T01:30:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"탐정은 사유했다. 어째서 그의 요청을 들어야 하는가?","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122438","time":"2026-07-23T01:30:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그 질문의 답은 간단하다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122439","time":"2026-07-23T01:31:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"저는 아직 검은 마녀를 막지 못했습니다.\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122440","time":"2026-07-23T01:31:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"아니.. 애초에 제가 감히 막을 힘이 있는지도 여전히 의문이 듭니다.\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122441","time":"2026-07-23T01:33:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"하지만 저는 두렵습니다. 제가 실패하는 것 보다도...\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122442","time":"2026-07-23T01:33:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"그럼에도 아무것도 하지 못했다라는 사실이.. 가장 두렵습니다.\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122443","time":"2026-07-23T01:34:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"저는 할 수 있는 일이라면, 무엇이든 시도해 볼 겁니다. 그것이 제가 택한 합리입니다. 그러니...\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122444","time":"2026-07-23T01:34:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"탐정은 신중하게 생각해야 했다. 이 다음 말은 내뱉으면 주워 담지 못한다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122445","time":"2026-07-23T01:35:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"행동하기 전에 먼저 생각을 한다. 그렇게 탐정은 계속해서 사유했다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122446","time":"2026-07-23T01:35:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"■■■여, 그대에게 묻습니다.\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122447","time":"2026-07-23T01:35:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"이 또한 당신의 각본입니까?\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122448","time":"2026-07-23T01:37:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"탐정은 어느덧 느꼈다. 마치 실에 얽힌 꼭두각시가 된... 아니. 이미 무대 위의 인형에 지나지 않았다는 자각.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122449","time":"2026-07-23T01:38:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"하지만 운명에 저항한 다느니, 그런 소리는 탐정에게 어울리지 않았다. 그렇다고 순응이냐면 그 또한 아니다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122450","time":"2026-07-23T01:38:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그리하여 그의 선택은....","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122451","time":"2026-07-23T01:43:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"예. 저 도리안은, '이름 없는 주인'에게 '어두운 힘'을 얻는 대가로 '이상'을 바치겠습니다.\"","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122452","time":"2026-07-23T01:44:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"가장 소중한 것을 바치는 것이 약속이었으니. 그것이 합당 할 터였다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122453","time":"2026-07-23T01:45:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그리고 이내, 탐정이 서있는 길이 무너져내렸다.","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122454","time":"2026-07-23T01:45:00+09:00","room":"RP II","name":"도리안 바이덴스","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-dd70a1273f02"]},{"id":"RP-II-0122455","time":"2026-07-23T01:45:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
